fetch("tutos/json/biblio-seo.json").then(e=>e.json()).then(e=>{let a=document.getElementById("bibliographie");e.forEach(e=>{let r=document.createElement("div");r.className="col-12 col-sm-6 col-md-4 col-lg-3";let l=document.createElement("div");l.className="card h-100",l.innerHTML=`
          <a href="${e.affiliate_link}" target="_blank" rel="noopener noreferrer">
            <img src="${e.image}" class="card-img-top" alt="${e.title}">
          </a>
          <div class="card-body d-flex flex-column">
            <h5 class="card-title">
              <a href="${e.affiliate_link}" target="_blank" rel="noopener noreferrer" class="text-decoration-none">${e.title}</a>
            </h5>
            <p class="card-text"><strong>${e.author}</strong></p>
            <p class="card-text flex-grow-1"><small>${e.summary}</small></p>
            <a href="${e.affiliate_link}" target="_blank" rel="noopener noreferrer" class="btn btn-primary mt-auto">Voir sur Amazon</a>
          </div>
        `,r.appendChild(l),a.appendChild(r)})}).catch(e=>console.error("Erreur chargement biblio.json:",e));